from pathlib import Path
import json,re

ROOT=Path('.')
INDEX=ROOT/'index.html'
OUT=ROOT/'trends'/'index.html'
if not INDEX.exists(): raise RuntimeError('index.html not found')
src=INDEX.read_text(encoding='utf-8')
m=re.search(r'const DATA=(\{.*?\});\nconst DRAFTS=',src,re.S)
if not m: raise RuntimeError('Could not locate DATA object in index.html')
data=json.loads(m.group(1))
editorial=[{'name':h.get('name'),'lane':h.get('lane'),'role':h.get('role'),'tier':h.get('tier')} for h in data.get('heroes',[]) if h.get('name')]
if len(editorial)<30: raise RuntimeError(f'Editorial pool too small: {len(editorial)}')
EDITORIAL=json.dumps(editorial,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')

page=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MLBB Trends · Live + Editorial | Meta Forge</title><meta name="description" content="Tendencias MLBB en dos capas: estadísticas live del roster completo y análisis editorial curado."><link rel="canonical" href="https://juanggm04-ship-it.github.io/mlbb-meta-forge/trends/"><style>
:root{{--bg:#070a12;--card:#0b1321;--line:#24324c;--text:#edf4ff;--muted:#8292ad;--cyan:#49e3ff;--green:#78e5af;--red:#ff9b9b;--purple:#b58cff;--gold:#ffd36c}}*{{box-sizing:border-box}}body{{margin:0;background:radial-gradient(circle at 13% 0,#152746 0,transparent 31%),var(--bg);color:var(--text);font-family:system-ui,-apple-system,sans-serif}}a{{color:inherit;text-decoration:none}}main{{max-width:1180px;margin:auto;padding:28px 18px 70px}}.top{{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}}.back{{color:var(--cyan);font-weight:850}}.pill{{display:inline-flex;padding:6px 9px;border:1px solid #30415e;border-radius:999px;font-size:10px;color:#c9d5e7}}.hero{{margin-top:20px;padding:28px;border:1px solid var(--line);border-radius:28px;background:linear-gradient(145deg,#0d1627,#17132b)}}.eyebrow{{color:var(--cyan);font-size:11px;font-weight:900;letter-spacing:.13em}}h1{{font-size:clamp(42px,8vw,76px);line-height:.95;letter-spacing:-.06em;margin:12px 0}}p{{color:#a7b4ca;line-height:1.65}}.modes{{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}}.mode{{border:1px solid #30415e;background:#0b1422;color:#aebdd3;border-radius:12px;padding:10px 12px;font-weight:900;cursor:pointer}}.mode.active{{background:linear-gradient(135deg,#45e5ff,#8b5cff);color:#07101a;border-color:transparent}}.mode small{{display:block;font-weight:650;opacity:.78;margin-top:3px}}.filters{{display:grid;grid-template-columns:1.35fr .8fr .8fr;gap:10px;margin-top:14px}}input,select{{width:100%;background:#09111d;border:1px solid #2a3b58;color:var(--text);border-radius:12px;padding:12px 13px}}select:disabled{{opacity:.42}}.status{{margin-top:12px;color:var(--muted);font-size:12px}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}}.panel,.all{{padding:18px;border:1px solid var(--line);border-radius:19px;background:#0a111e}}.panel h2,.all h2{{margin:0 0 12px;font-size:19px}}.list,.table{{display:grid;gap:8px}}.row{{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:10px;align-items:center;padding:10px 11px;border:1px solid #22314a;border-radius:12px;background:#0d1625}}.row b{{font-size:13px}}.meta{{font-size:10px;color:var(--muted);margin-top:3px}}.delta{{font-size:12px;font-weight:900}}.up{{color:var(--green)}}.down{{color:var(--red)}}.flat{{color:#9aa8be}}.spark{{width:88px;height:28px}}.all{{margin-top:14px}}.trow{{display:grid;grid-template-columns:minmax(140px,1.4fr) .7fr .7fr .7fr .9fr auto;gap:9px;align-items:center;padding:10px 12px;border-bottom:1px solid #182338}}.trow.head{{font-size:10px;color:var(--muted);font-weight:900;letter-spacing:.08em}}.tag{{display:inline-flex;padding:4px 7px;border-radius:999px;border:1px solid #31435f;font-size:9px;font-weight:900;margin-left:6px}}.tag.live{{color:#5be8ff}}.tag.ed{{color:#cbb0ff;border-color:#694da7}}.empty{{color:var(--muted);font-size:12px;padding:14px 0}}.watch{{border:1px solid #33445f;background:#101a2c;color:#dce7f8;border-radius:9px;padding:7px 9px;cursor:pointer;font-size:11px}}@media(max-width:760px){{.filters,.grid{{grid-template-columns:1fr}}.trow{{grid-template-columns:1.3fr .8fr .8fr auto}}.hide-mob{{display:none}}.spark{{width:66px}}}}</style></head><body><main><div class="top"><a class="back" href="../">← Meta Forge</a><div><a class="pill" href="../roster/">Live Roster</a> <a class="pill" href="../heroes/">Editorial</a></div></div><section class="hero"><div class="eyebrow">META TRENDS</div><h1>Dos capas. Una lectura más limpia.</h1><p>Explora el roster completo con estadísticas live o limita la vista al pool editorial cuando quieras línea, rol y análisis estratégico. Nunca rellenamos con supuestos lo que la fuente no trae.</p><div class="modes"><button id="trendModeLive" class="mode active" type="button">LIVE · TODOS<small>133 héroes · WR / ban / pick</small></button><button id="trendModeEditorial" class="mode" type="button">EDITORIAL<small>34 héroes · línea / rol / tier</small></button></div><div class="filters"><input id="q" type="search" placeholder="Buscar héroe…" aria-label="Buscar héroe"><select id="lane" disabled><option value="">Todas las líneas</option></select><select id="role" disabled><option value="">Todos los roles</option></select></div><div id="status" class="status">Cargando snapshots…</div></section><section class="grid"><article class="panel"><h2>📈 Risers por WR</h2><div id="risers" class="list"></div></article><article class="panel"><h2>📉 Fallers por WR</h2><div id="fallers" class="list"></div></article><article class="panel"><h2>🚨 Movimiento de bans</h2><div id="banmoves" class="list"></div></article><article class="panel"><h2>🔥 Ban rate actual</h2><div id="contested" class="list"></div></article></section><section class="all"><h2>Explorador</h2><div class="table"><div class="trow head"><span>HÉROE</span><span>WR Δ</span><span>BAN Δ</span><span class="hide-mob">WR</span><span class="hide-mob">LECTURA</span><span></span></div><div id="allRows"></div></div></section></main><script>
const EDITORIAL={EDITORIAL};
const slug=n=>n.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const load=async p=>{{try{{const r=await fetch(p,{{cache:'no-store'}});return r.ok?await r.json():null}}catch{{return null}}}};
const fmt=v=>Number.isFinite(v)?`${{v>0?'+':''}}${{v.toFixed(2)}} pp`:'—';
const pct=v=>Number.isFinite(v)?v.toFixed(2)+'%':'—';
const spark=vals=>{{vals=vals.filter(Number.isFinite);if(vals.length<2)return '<span class="meta">sin serie</span>';const w=88,h=28,min=Math.min(...vals),max=Math.max(...vals),d=(max-min)||1;const pts=vals.map((v,i)=>`${{(i/(vals.length-1))*w}},${{h-3-((v-min)/d)*(h-6)}}`).join(' ');return `<svg class="spark" viewBox="0 0 ${{w}} ${{h}}" aria-hidden="true"><polyline fill="none" stroke="currentColor" stroke-width="2" points="${{pts}}"/></svg>`}};
function classify(series){{const v=series.filter(Number.isFinite);if(v.length<2)return 'Sin serie';const d=v.at(-1)-v[0],range=Math.max(...v)-Math.min(...v);if(range>=2.5)return 'Volátil';if(d>=.6)return 'Subiendo';if(d<=-.6)return 'Bajando';return 'Estable'}}
(async()=>{{
 const [cur,prev,hist]=await Promise.all([load('../data/live-meta.json'),load('../data/previous-meta.json'),load('../data/meta-history.json')]);
 const snapshots=Array.isArray(hist)?hist:(hist?.snapshots||[]);const C=new Map((cur?.heroes||[]).map(h=>[h.name,h])),P=new Map((prev?.heroes||[]).map(h=>[h.name,h]));const EM=new Map(EDITORIAL.map(h=>[h.name,h]));
 const rows=(cur?.heroes||[]).filter(h=>h.name).map(c=>{{const p=P.get(c.name),e=EM.get(c.name)||null;const series=snapshots.map(s=>(s.heroes||[]).find(x=>x.name===c.name)?.wr).filter(Number.isFinite);return {{name:c.name,c,p,e,series,wrDelta:p&&Number.isFinite(c.wr)&&Number.isFinite(p.wr)?c.wr-p.wr:null,banDelta:p&&Number.isFinite(c.ban)&&Number.isFinite(p.ban)?c.ban-p.ban:null}}}});
 const lanes=[...new Set(EDITORIAL.map(h=>h.lane).filter(Boolean))].sort(),roles=[...new Set(EDITORIAL.map(h=>h.role).filter(Boolean))].sort();lane.innerHTML+=lanes.map(x=>`<option>${{x}}</option>`).join('');role.innerHTML+=roles.map(x=>`<option>${{x}}</option>`).join('');
 let mode='live';
 const href=r=>mode==='editorial'&&r.e?`../heroes/${{slug(r.name)}}/`:`../stats/heroes/${{slug(r.name)}}/`;
 const sub=r=>mode==='editorial'&&r.e?`${{r.e.lane||'—'}} · ${{r.e.role||'—'}} · tier ${{r.e.tier||'—'}}`:'Live stats · snapshot público';
 const card=(r,key)=>`<div class="row"><a href="${{href(r)}}"><b>${{r.name}}</b><div class="meta">${{sub(r)}}</div></a><span class="delta ${{r[key]>0?'up':r[key]<0?'down':'flat'}}">${{fmt(r[key])}}</span><span class="${{r[key]>=0?'up':'down'}}">${{spark(r.series)}}</span></div>`;
 function filtered(){{const qq=q.value.trim().toLowerCase();return rows.filter(r=>(mode==='live'||r.e)&&(!qq||r.name.toLowerCase().includes(qq))&&(mode!=='editorial'||!lane.value||r.e?.lane===lane.value)&&(mode!=='editorial'||!role.value||r.e?.role===role.value))}}
 function setMode(next){{mode=next;trendModeLive.classList.toggle('active',mode==='live');trendModeEditorial.classList.toggle('active',mode==='editorial');lane.disabled=role.disabled=mode!=='editorial';if(mode==='live'){{lane.value='';role.value=''}}render()}}
 function render(){{const f=filtered(),wr=f.filter(r=>Number.isFinite(r.wrDelta)),ban=f.filter(r=>Number.isFinite(r.banDelta)),now=f.filter(r=>Number.isFinite(r.c?.ban));risers.innerHTML=[...wr].sort((a,b)=>b.wrDelta-a.wrDelta).slice(0,6).map(r=>card(r,'wrDelta')).join('')||'<div class="empty">Esperando otro snapshot distinto.</div>';fallers.innerHTML=[...wr].sort((a,b)=>a.wrDelta-b.wrDelta).slice(0,6).map(r=>card(r,'wrDelta')).join('')||'<div class="empty">Esperando otro snapshot distinto.</div>';banmoves.innerHTML=[...ban].sort((a,b)=>Math.abs(b.banDelta)-Math.abs(a.banDelta)).slice(0,6).map(r=>card(r,'banDelta')).join('')||'<div class="empty">Sin comparación de bans todavía.</div>';contested.innerHTML=[...now].sort((a,b)=>b.c.ban-a.c.ban).slice(0,6).map(r=>`<div class="row"><a href="${{href(r)}}"><b>${{r.name}}</b><div class="meta">${{sub(r)}}</div></a><span class="delta">${{pct(r.c.ban)}}</span><span>${{spark(r.series)}}</span></div>`).join('')||'<div class="empty">Sin ban rate disponible.</div>';allRows.innerHTML=[...f].sort((a,b)=>(b.c?.wr??-1)-(a.c?.wr??-1)).map(r=>`<div class="trow"><a href="${{href(r)}}"><b>${{r.name}}</b>${{r.e?'<span class="tag ed">EDITORIAL</span>':'<span class="tag live">LIVE</span>'}}<div class="meta">${{sub(r)}}</div></a><span class="${{r.wrDelta>0?'up':r.wrDelta<0?'down':'flat'}}">${{fmt(r.wrDelta)}}</span><span class="${{r.banDelta>0?'up':r.banDelta<0?'down':'flat'}}">${{fmt(r.banDelta)}}</span><span class="hide-mob">${{pct(r.c?.wr)}}</span><span class="hide-mob">${{classify(r.series)}}</span><button class="watch" type="button" data-watch-hero="${{r.name}}">☆ Seguir</button></div>`).join('')||'<div class="empty">No hay héroes con esos filtros.</div>';status.textContent=`${{f.length}} héroes · ${{mode==='live'?'cobertura estadística live':'pool editorial curado'}} · ${{snapshots.length}} snapshots · ${{cur?.patch||'patch sin dato'}}`;}}
 trendModeLive.onclick=()=>setMode('live');trendModeEditorial.onclick=()=>setMode('editorial');q.oninput=lane.onchange=role.onchange=render;render();
}})();
</script></body></html>'''
OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(page,encoding='utf-8')

home=INDEX.read_text(encoding='utf-8')
if 'href="trends/"' not in home:
    quick='<a class="quick-action" href="trends/"><b>↗ Meta Trends</b><span>Live 133 + análisis editorial en una sola vista.</span></a>'
    marker='<div id="homeQuickActions" class="quick-actions">'
    if marker in home: home=home.replace(marker,marker+quick,1)
    INDEX.write_text(home,encoding='utf-8')

smap=ROOT/'sitemap.xml'
if smap.exists():
    s=smap.read_text(encoding='utf-8');url='<url><loc>https://juanggm04-ship-it.github.io/mlbb-meta-forge/trends/</loc></url>'
    if '/trends/' not in s: s=s.replace('</urlset>',url+'</urlset>');smap.write_text(s,encoding='utf-8')
print(f'Generated dual Trends: live roster + {len(editorial)} editorial heroes')
